{
  "name": "@niebaopeng/ocusage",
  "version": "1.0.6",
  "description": "Usage analysis tool for OpenCode / Kimi CLI sessions",
  "type": "module",
  "main": "./dist/index.js",
  "module": "./dist/index.js",
  "bin": {
    "ocusage": "./dist/index.js"
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "tsup src/index.ts --format esm --out-dir dist --clean --minify --external node:sqlite",
    "dev": "tsup src/index.ts --format esm --out-dir dist --watch --sourcemap",
    "start": "node dist/index.js",
    "typecheck": "tsc --noEmit"
  },
  "keywords": [
    "kimi-cli",
    "opencode",
    "usage",
    "tokens",
    "cli"
  ],
  "license": "MIT",
  "dependencies": {
    "cli-table3": "^0.6.5",
    "picocolors": "^1.1.1",
    "valibot": "^1.1.1"
  },
  "devDependencies": {
    "@types/node": "^22.14.0",
    "tsup": "^8.4.0",
    "typescript": "^5.8.2"
  },
  "engines": {
    "node": ">=20"
  }
}
